package ktanesolver.module.modded.regular.ikea;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class IkeaSolverTest{private final IkeaSolver solver=new IkeaSolver();
	@Test void mapsBlueProductRankingBitsAndMazePathToButtons(){IkeaOutput out=solve(List.of(button("SÄNG",IkeaInput.Color.BLUE),button("KÖTTBULLE",IkeaInput.Color.YELLOW),button("SKÅL",IkeaInput.Color.BLUE),button("OST",IkeaInput.Color.YELLOW),button("TROLLKARL",IkeaInput.Color.BLUE)));assertThat(out.storeNumber()).isEqualTo(10);assertThat(out.buttonDirections()).containsExactly("X","N","E","W","S");assertThat(out.path()).isEqualTo("WWNNWNNEEENE");assertThat(out.presses()).containsExactly(4,4,2,2,4,2,2,3,3,3,2,3);}
	@Test void acceptsEnglishDictionaryAliases(){IkeaOutput out=solve(List.of(button("bed",IkeaInput.Color.BLUE),button("meatball",IkeaInput.Color.BLUE),button("bowl",IkeaInput.Color.BLUE),button("cheese",IkeaInput.Color.BLUE),button("wizard",IkeaInput.Color.BLUE)));assertThat(out.storeNumber()).isZero();assertThat(out.buttonDirections()).containsExactly("X","N","E","W","S");}
	@Test void rejectsMissingProductAndDuplicateBrands(){assertFailure(List.of(button("MEATBALL",IkeaInput.Color.BLUE),button("BOWL",IkeaInput.Color.BLUE),button("CHEESE",IkeaInput.Color.BLUE),button("WIZARD",IkeaInput.Color.BLUE),button("SHOE",IkeaInput.Color.BLUE)));assertFailure(List.of(button("BED",IkeaInput.Color.BLUE),button("MEATBALL",IkeaInput.Color.BLUE),button("MEATBALL",IkeaInput.Color.YELLOW),button("CHEESE",IkeaInput.Color.BLUE),button("WIZARD",IkeaInput.Color.BLUE)));}
	private void assertFailure(List<IkeaInput.Button>buttons){assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new IkeaInput(buttons))).isInstanceOf(SolveFailure.class);}@SuppressWarnings("unchecked")private IkeaOutput solve(List<IkeaInput.Button>buttons){return((SolveSuccess<IkeaOutput>)solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new IkeaInput(buttons))).output();}private static IkeaInput.Button button(String label,IkeaInput.Color color){return new IkeaInput.Button(label,color);}}
